def match(tgt, opts=None):
    """
    Matches based on IP address or CIDR notation
    """
    if not isinstance(tgt, (list, tuple)):
        tgt = [tgt]

    if opts is None:
        opts = {}

    ret = []
    for tgtitem in tgt:
        if "/" in tgtitem:
            ip, mask = tgtitem.split("/")
            ipaddr = ipaddress.ip_address(ip)
            mask = int(mask)
            ret.append(ipaddr.network(mask))
        else:
            ret.append(ipaddress.ip_address(tgtitem))

    return ret

