def parse_host(host, opts=None):
    """
    Parse a host and return the ip address and hostname
    """
    if opts is None:
        opts = {}

    if ":" in host:
        host, port = host.split(":")
        port = int(port)
    else:
        port = None

    if "@" in host:
        user, host = host.split("@")
    else:
        user = None

    if opts.get("use_ipv6", False):
        host = host.lower()

    if "." in host:
        hostname = host
        ipaddr = host
    else:
        hostname = None
        ipaddr = host

    return user, ipaddr, hostname, port


